"""Coverage calibration, score filtering and table-entry accounting.

The legacy coverage filter compared sampled generators and printed progress to
stderr; the contract instead needs exact per-class validation coverage of the
generalized interval, an exact rational score and the resulting kept/priority
selection shared across classes and lengths.
"""
from fractions import Fraction
from itertools import product

import numpy as np

PAD = 1514
VALUE_MAX = 3028
SCORE_FLOOR = Fraction(1, 10000)


def _row_matrix(rows):
    """Padded int16 matrix of real prefixes; padding never matches a bound."""
    count = len(rows)
    widest = 0
    for _, values in rows:
        if len(values) > widest:
            widest = len(values)
    matrix = np.full((count, widest), -1, dtype=np.int16)
    lengths = np.zeros(count, dtype=np.int64)
    labels = np.zeros(count, dtype=np.int64)
    low = np.full(count, VALUE_MAX+1, dtype=np.int32)
    high = np.full(count, -1, dtype=np.int32)
    for index, (label, values) in enumerate(rows):
        size = len(values)
        labels[index] = label
        lengths[index] = size
        if size:
            matrix[index, :size] = values
            low[index] = min(values)
            high[index] = max(values)
    return matrix, lengths, labels, low, high


def _pattern_rows(matrix, low, high, labels, lengths, length):
    usable = lengths >= length
    if not usable.any():
        return None
    if usable.all():
        return matrix, low, high, labels
    return matrix[usable], low[usable], high[usable], labels[usable]


def _coverage(sub, low, high, labels, bounds, classes, widest, length):
    """Validation rows holding at least one window inside every interval."""
    rows = sub.shape[0]
    possible = np.ones(rows, dtype=bool)
    for axis in range(length):
        lo, hi = bounds[axis]
        possible &= (low <= hi) & (high >= lo)
    chosen = np.nonzero(possible)[0]
    if chosen.size == 0:
        return [0]*classes
    block = sub if chosen.size == rows else sub[chosen]
    window = block.shape[1]-length+1
    lo, hi = bounds[0]
    starts = (block[:, 0:window] >= lo) & (block[:, 0:window] <= hi)
    row_index, offset = np.nonzero(starts)
    for axis in range(1, length):
        if row_index.size == 0:
            break
        lo, hi = bounds[axis]
        values = block[row_index, offset+axis]
        keep = (values >= lo) & (values <= hi)
        row_index = row_index[keep]
        offset = offset[keep]
    if row_index.size == 0:
        return [0]*classes
    hit = np.zeros(chosen.size, dtype=bool)
    hit[row_index] = True
    matched = labels[chosen] if chosen.size == rows else labels[chosen][hit]
    if chosen.size == rows:
        matched = labels[hit]
    return np.bincount(matched, minlength=classes).tolist()


def calibrate(patterns, rows, classes):
    """hits per class for every generalized interval pattern.

    `patterns` is a list of (key, bounds); identical patterns share one
    coverage computation. Returns {key: hits list}.
    """
    result = {}
    if not patterns or not rows:
        for key, _ in patterns:
            result.setdefault(key, [0]*classes)
        return result
    matrix, lengths, labels, low, high = _row_matrix(rows)
    widest = matrix.shape[1]
    cache = {}
    for key, bounds in patterns:
        if key in result:
            continue
        length = len(bounds)
        state = cache.get(length)
        if state is None:
            state = cache[length] = _pattern_rows(matrix, low, high, labels, lengths, length)
        if state is None:
            result[key] = [0]*classes
            continue
        result[key] = _coverage(state[0], state[1], state[2], state[3], bounds,
                                classes, widest, length)
    return result


def score_cluster(hits, counts, target):
    """Cin/(Cout+1/10000) with exact rational arithmetic."""
    inside = Fraction(hits[target], counts[target])
    outside = Fraction(0)
    for label in range(len(counts)):
        if label == target:
            continue
        candidate = Fraction(hits[label], counts[label])
        if candidate > outside:
            outside = candidate
    return inside/(outside+SCORE_FLOOR)


def kept_and_priority(scores, threshold):
    """Decreasing exact score, then increasing cluster id."""
    kept = [identity for identity, value in scores.items() if value > threshold]
    kept.sort(key=lambda identity: (-scores[identity], identity))
    return kept


def _key_count(bounds):
    total = 1
    for lo, hi in bounds:
        span = hi-lo+1
        if lo <= PAD <= hi:
            span -= 1
        if span <= 0:
            return 0
        total *= span
    return total


def _key_values(lo, hi):
    if lo <= PAD <= hi:
        return list(range(lo, PAD))+list(range(PAD+1, hi+1))
    return list(range(lo, hi+1))


def _drop_contained(boxes):
    """Remove boxes covered by another box (same-length Cartesian products)."""
    size = len(boxes)
    if size <= 2:
        return boxes
    lows = np.array([box[0] for box in boxes], dtype=np.int32)
    highs = np.array([box[1] for box in boxes], dtype=np.int32)
    if size <= 48:
        keep = []
        for index in range(size):
            covered = False
            for other in range(size):
                if other == index:
                    continue
                if bool(np.all(lows[other] <= lows[index]) and np.all(highs[index] <= highs[other])):
                    covered = True
                    break
            if not covered:
                keep.append(boxes[index])
        return keep
    keep = np.ones(size, dtype=bool)
    step = max(1, (1 << 22)//max(1, size*lows.shape[1]))
    for start in range(0, size, step):
        stop = min(size, start+step)
        inner = ((lows[None, start:stop, :] >= lows[:, None, :]) &
                 (highs[start:stop, None, :] >= highs[:, None, :])).all(axis=-1)
        # inner[candidate, index]: candidate box contains boxes[index]
        covered = inner.sum(axis=1) > 1
        keep[start:stop] = ~covered
    return [boxes[index] for index in range(size) if keep[index]]


def exact_entry_count(pattern_bounds, cap):
    """min(distinct exact keys, cap) with 1514 excluded at every coordinate."""
    if not pattern_bounds:
        return 0
    if cap <= 1:
        for bounds in pattern_bounds:
            if _key_count(bounds) > 0:
                return cap
        return 0
    distinct = {}
    for bounds in pattern_bounds:
        total = _key_count(bounds)
        if total == 0:
            continue
        if total >= cap:
            return cap
        key = tuple(tuple(pair) for pair in bounds)
        previous = distinct.get(key)
        if previous is None or total > previous[1]:
            distinct[key] = (bounds, total)
    boxes = list(distinct.values())
    if not boxes:
        return 0
    boxes = _drop_contained(boxes)
    boxes.sort(key=lambda item: -item[1])
    keys = set()
    for bounds, _ in boxes:
        axes = [_key_values(lo, hi) for lo, hi in bounds]
        for key in product(*axes):
            keys.add(key)
            if len(keys) >= cap:
                return cap
    return len(keys)
